-- 学习's courses, which began in the code. An administrator opens one with a sentence (`request`)
-- and XABC opens one a week at most from what the site's news keeps returning to (`news`); XABC
-- designs each from its idea. Courses stand in groups, in the order they came (`place`), and a
-- hidden one is neither listed nor extended. A lesson names its course.
CREATE TABLE courses (
    id text PRIMARY KEY CHECK (id ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND char_length(id) <= 40),
    place integer GENERATED ALWAYS AS IDENTITY,
    grp text NOT NULL CHECK (char_length(grp) BETWEEN 1 AND 20),
    grp_en text NOT NULL CHECK (char_length(grp_en) BETWEEN 1 AND 60),
    title text NOT NULL CHECK (char_length(title) BETWEEN 1 AND 40),
    title_en text NOT NULL CHECK (char_length(title_en) BETWEEN 1 AND 80),
    intro text NOT NULL CHECK (char_length(intro) BETWEEN 1 AND 120),
    intro_en text NOT NULL CHECK (char_length(intro_en) BETWEEN 1 AND 240),
    brief text NOT NULL CHECK (char_length(brief) BETWEEN 1 AND 4000),
    idea text NOT NULL DEFAULT '',
    source text NOT NULL CHECK (source IN ('seed', 'request', 'news')),
    visible boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now()
);
INSERT INTO courses (id, grp, grp_en, title, title_en, intro, intro_en, brief, source) VALUES
    ($c$basics$c$, $c$AI 入门与应用$c$, $c$Getting started with AI$c$, $c$AI 入门$c$, $c$AI Basics$c$, $c$从零认识大模型：它能做什么、怎么用好、怎么选$c$, $c$Large language models from zero: what they do, how to use them well and how to choose$c$, $c$读者是刚开始接触 AI 的普通人，不需要编程基础。建议的章节路线：大模型是什么、能做什么不能做什么 → token、上下文与幻觉 → 主流模型和产品（ChatGPT、Claude、Gemini、Grok、DeepSeek、通义千问、Kimi、豆包等）怎么选，免费与付费订阅怎么选 → 日常用法：问答、写作、翻译、总结、学习与搜索 → 多模态：看图、语音、文件与长文档 → 记忆、项目与自定义助手 → 隐私、安全与辨别 AI 内容 → 用 AI 持续学习与提效。讲概念多用生活里的类比，少用术语，用到时先解释。$c$, 'seed'),
    ($c$prompts$c$, $c$AI 入门与应用$c$, $c$Getting started with AI$c$, $c$提示词$c$, $c$Prompting$c$, $c$把需求说清楚：结构化提示、举例、让模型自查$c$, $c$Saying what you want: structured prompts, examples and self-checks$c$, $c$读者会用聊天式 AI，想让它稳定地给出好结果。建议的章节路线：好提示词的要素（目标、背景、约束、格式）→ 角色与语气 → 举例（少样本）→ 拆解复杂任务与分步推理 → 结构化输出（表格、JSON）→ 让模型自查与改写 → 长文档与资料的提问方法 → 推理模型与普通模型的提示差异 → 写作、编程、数据分析和学习等场景的提示模板 → 评测与迭代提示词，提示注入与防护。每课给出能直接复制使用的提示词，以及改进前后的对比。$c$, 'seed'),
    ($c$create$c$, $c$AI 入门与应用$c$, $c$Getting started with AI$c$, $c$AI 创作与提效$c$, $c$Creating with AI$c$, $c$用 AI 画图、做视频和语音，写作、办公与研究提效$c$, $c$Images, video and voice with AI, and faster writing, office work and research$c$, $c$读者是创作者和职场人，不需要编程。建议的章节路线：图像生成（GPT Image、Midjourney、即梦等）的提示与风格 → 图像编辑与角色一致性 → 视频生成（Sora、Veo、可灵、Grok Imagine 等）→ 语音合成、配音与音乐 → 写作与编辑 → 办公：文档、表格、演示与会议纪要 → 研究与深度搜索 → 数据分析与图表 → 学习与知识管理 → 自动化工作流 → 版权、标注与合规。工具变得快，课里写明工具的版本和日期，优先讲能迁移到别的工具的方法。$c$, 'seed'),
    ($c$coding$c$, $c$AI 开发$c$, $c$Building with AI$c$, $c$AI 编程$c$, $c$AI Coding$c$, $c$Claude Code、Codex、Cursor 等工具，从安装到专业工作流$c$, $c$Claude Code, Codex, Cursor and more, from setup to professional workflows$c$, $c$读者是开发者，或想用 AI 写代码的人。建议的章节路线：AI 编程工具全景与怎么选（Claude Code、OpenAI Codex、Cursor、GitHub Copilot、Gemini CLI 等）→ 安装、登录与计费方式 → 第一个项目：让 AI 读懂代码库、改代码、跑测试 → 项目说明文件（如 CLAUDE.md、AGENTS.md）与上下文管理 → 计划模式、审查改动与版本控制 → 测试驱动与调试 → 重构与大型项目 → 子代理、并行任务与自动化（hooks、自定义命令、在 CI 中运行）→ 用 MCP 接入外部工具 → 代码审查与安全 → 成本与额度控制 → 团队协作与规范。命令、配置和快捷键以各工具官方文档的最新版本为准，写明版本。$c$, 'seed'),
    ($c$agents$c$, $c$AI 开发$c$, $c$Building with AI$c$, $c$Agent 与 MCP$c$, $c$Agents & MCP$c$, $c$工具调用、MCP、自动化工作流与多 Agent$c$, $c$Tool calling, MCP, automated workflows and multi-agent systems$c$, $c$读者有一些编程基础。建议的章节路线：Agent 是什么、和聊天有什么不同 → 函数调用与工具调用的原理和 API 写法 → 设计好用的工具 → MCP 协议：概念与使用现成的 MCP 服务器 → 自己写 MCP 服务器（Python、TypeScript）→ 远程 MCP 与认证 → Agent 框架与 SDK（OpenAI Agents SDK、Claude Agent SDK、LangGraph 等）→ 规划、记忆与长任务 → 多 Agent 协作 → 操作浏览器与电脑 → 评测、可观测性与成本 → 安全：权限、提示注入与沙箱 → 实战项目。代码以官方 SDK 文档为准，写明版本。$c$, 'seed'),
    ($c$rag$c$, $c$AI 开发$c$, $c$Building with AI$c$, $c$RAG 与知识库$c$, $c$RAG & Knowledge Bases$c$, $c$让 AI 用上你的资料：嵌入、检索与知识库$c$, $c$Putting your own documents to work: embeddings, retrieval and knowledge bases$c$, $c$读者有一些编程基础。建议的章节路线：RAG 是什么、什么时候用（与长上下文、微调对比）→ 嵌入与向量相似度 → 文档解析与切分 → 向量数据库（pgvector、Milvus、Qdrant 等）与选型 → 检索：混合检索与重排 → 组装提示与引用来源 → 评测：召回率与忠实度 → 进阶：查询改写、多跳检索、GraphRAG、Agentic RAG → 多模态 RAG → 生产化：增量更新、权限、成本与延迟 → 现成方案（Dify、RAGFlow 等）与自建的取舍 → 实战项目。示例代码给出能运行的最小版本，写明库的版本。$c$, 'seed'),
    ($c$api$c$, $c$AI 开发$c$, $c$Building with AI$c$, $c$模型 API 开发$c$, $c$Model APIs$c$, $c$调用大模型 API：流式、结构化输出、缓存与成本$c$, $c$Building on model APIs: streaming, structured output, caching and cost$c$, $c$读者是开发者。建议的章节路线：主流 API 全景（OpenAI、Anthropic、Gemini、xAI、DeepSeek、通义千问等）与 Key 管理 → 第一次调用（Python、TypeScript、curl）→ 消息、角色与参数 → 流式输出 → 结构化输出与 JSON Schema → 工具调用 → 多模态输入：图片、PDF 与音频 → 图像、语音与嵌入接口 → 提示缓存与批处理 → token 计算、价格与成本控制（各家官方价格可以引用本站汇总的大模型价格表 https://xabcnews.com/llm）→ 错误处理、重试与限流 → 兼容接口与多模型切换 → 安全与合规 → 生产部署。接口、参数和价格以各家官方文档为准，写明日期。$c$, 'seed'),
    ($c$local$c$, $c$AI 开发$c$, $c$Building with AI$c$, $c$开源与本地模型$c$, $c$Open & Local Models$c$, $c$在自己的电脑和服务器上跑模型：部署、量化与微调$c$, $c$Running models on your own machines: deployment, quantization and fine-tuning$c$, $c$读者有一些命令行基础。建议的章节路线：开源模型全景（Qwen、DeepSeek、Llama、Gemma、Mistral 等）与许可证 → 硬件怎么选：显存、内存与 Apple Silicon → Ollama、LM Studio 快速上手 → llama.cpp 与 GGUF，量化的原理与选择 → vLLM、SGLang 等推理服务 → 把本地模型接入编辑器、聊天界面与 Agent → 性能调优与多卡 → 微调：LoRA、QLoRA 与数据准备 → 评测 → 部署到服务器与成本 → 端侧与移动端 → 实战项目。命令和版本以各项目官方文档为准。$c$, 'seed'),
    ($c$esp32$c$, $c$硬件与嵌入式$c$, $c$Hardware and embedded$c$, $c$ESP32$c$, $c$ESP32$c$, $c$用 ESP-IDF 做商业级产品：从选型、量产到端侧与云端 AI$c$, $c$Commercial products with ESP-IDF, from choosing a chip to mass production and AI on the device and in the cloud$c$, $c$只讲乐鑫官方的专业开发路线：ESP-IDF（C 语言，FreeRTOS）、官方工具链（idf.py、VS Code 的 ESP-IDF 插件）和乐鑫官方的组件与框架；不讲 Arduino、MicroPython 和 PlatformIO。读者会 C 语言，目标是做出能量产、能上市的产品。默认开发板是 ESP32-S3（N16R8），语音和视觉需要它的算力与 PSRAM；Matter 与 Thread 用 ESP32-C6 或 H2，屏幕与多媒体用 ESP32-P4。建议的章节路线：芯片与选型（全系列对比、模组与量产型号、BOM 成本）→ ESP-IDF 工程化（安装、工程结构、组件与 CMake、Kconfig 与 menuconfig、组件管理器、JTAG 与 GDB 调试、日志与 core dump，用 AI 编程工具写和调试固件）→ FreeRTOS 与系统（任务与同步、内存与 PSRAM、分区表、NVS、看门狗）→ 外设与驱动（GPIO、LEDC、ADC、I²C、SPI、UART、RMT、I2S 音频、esp_lcd 屏幕与触摸、摄像头）→ 联网（Wi-Fi 与配网：BluFi、SoftAP；HTTPS、WebSocket、MQTT；NimBLE；ESP-NOW；Thread、Zigbee 与 Matter）→ 安全与量产（Secure Boot v2、Flash 加密、eFuse、TLS 证书、OTA 双分区与回滚、产测与烧录、ESP Insights、无线认证）→ 低功耗与产品化（Light Sleep、Deep Sleep、ULP、电源与可靠性）→ 端侧 AI（ESP-SR 的 AFE、唤醒词与命令词，ESP-DL 的模型部署与量化，ESP-WHO 视觉，ESP32-P4 的 AI 与多媒体）→ 接入大模型（HTTPS 调用大模型 API、流式输出、语音链路：识别、大模型、合成，实时语音，小智 AI 等开源项目的架构，用 MCP 让大模型控制设备）→ 实战项目（AI 语音硬件、Matter 智能家居设备、视觉终端）。API、配置项和命令以 ESP-IDF 官方编程指南的最新稳定版为准，写明适用的 ESP-IDF 版本和芯片。$c$, 'seed'),
    ($c$voice-assistant$c$, $c$实战项目$c$, $c$Projects$c$, $c$ESP32 AI 语音助手实战$c$, $c$Building an ESP32 AI Voice Assistant$c$, $c$用 ESP32 和大模型做一台能语音对话、云端管理、可自定义声色与性格的个人助手$c$, $c$A personal assistant on the ESP32 and large models: voice conversation, management in the cloud, and a voice and character of your own$c$, $c$实战项目课：从零做出一台完整的个人语音助手，并能上线使用。全课做同一个项目、用同一套技术栈，一课接一课往上加功能，每课在前面各课的代码上继续，第一课定下整体架构和代码仓库结构。设备端用 ESP-IDF（C 语言）和 ESP32-S3（N16R8，带麦克风与扬声器的开发板），不讲 Arduino；云端服务用 Python、FastAPI、WebSocket 和 PostgreSQL，用 Docker 部署；Web 管理台用 Vue 3 和 TypeScript。语音识别、大模型和语音合成既讲云端 API（OpenAI、Gemini 等实时语音接口，以及阿里云百炼、火山引擎等国内服务），也讲开源方案（如 FunASR、CosyVoice），说明各自的延迟、成本和适用场景；可以参考小智 AI 等开源项目的架构，但课程讲的是自己的完整实现。读者会 C 语言和一点 Python，ESP32 的基础知识需要时指向本站「ESP32」课程。建议的章节路线：产品与架构（设备、云端、管理台三部分和「唤醒 → 录音 → 识别 → 大模型 → 合成 → 播放」的数据流）→ 硬件与音频（I2S 麦克风与功放、ESP-SR 的回声消除、降噪与唤醒词）→ 设备固件（ESP-IDF 工程、Wi-Fi 配网、WebSocket 连接云端、Opus 流式音频、OTA）→ 云端语音链路（流式识别、大模型对话、流式合成与低延迟优化）→ 自定义声色（音色选择、声音克隆的技术与合规、语速与情绪参数）→ 性格与记忆（角色设定提示词、长期记忆、工具调用与用 MCP 控制设备）→ Web 管理台（账户、设备绑定、角色与声色配置、对话记录、配置下发）→ 安全、成本与量产（鉴权、隐私、费用控制、部署、批量烧录与 OTA）。命令、接口和版本以各官方文档为准，写明版本；声音克隆必须讲清授权同意和标识要求。$c$, 'seed');
